declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';$root=dirname(__DIR__,2);$controller=(string)@file_get_contents($root.'/app/YiiRuntime/Commands/WorkforceSyncController.php');$adapter=(string)@file_get_contents($root.'/app/YiiRuntime/WorkforceSyncConsole.php');$alias=(string)file_get_contents($root.'/bin/fmonitor2-sync-workforce.php');$jobs=(string)file_get_contents($root.'/app/Jobs/JobHandlerRuntime.php');
assertSameValue(true,$controller!==''&&$adapter!=='','INTENDED_RED: Yii workforce composition exists');$combined=$controller.$adapter;assertSameValue(1,substr_count($combined,'MariaDbWorkforceSynchronization'),'one owner composition');assertSameValue(1,substr_count($combined,'new mysqli'),'one connection construction');assertSameValue(true,str_contains($adapter,'finally')&&str_contains($adapter,'->close()'),'composition owns terminal connection release');assertSameValue(1,preg_match('~new mysqli.*try.*set_charset.*catch.*->close\(\)~s',$adapter),'partial database initialization closes before rethrow');foreach(['begin_transaction','INSERT INTO','UPDATE ','DELETE ','rapid-pilot','app/Otiz','yii\\db\\Connection','ActiveRecord']as$f)assertSameValue(false,str_contains($combined,$f),'no parallel owner '.$f);foreach(['new mysqli','MariaDbWorkforceSynchronization','BitrixWorkforceDeliveryFactory','WorkerConfiguration','set_charset']as$f)assertSameValue(false,str_contains($alias,$f),'alias delegates '.$f);assertSameValue(true,str_contains($alias,'fmonitor2-yii.php')&&str_contains($alias,'workforce-sync/run'),'alias exact Yii route');assertSameValue(true,str_contains($jobs,'WorkforceSyncConsole'),'jobs reuse shared composition');echo"PASS: YII2-WORKFORCE-SYNC-CONSOLE-001 ownership\n";
